package com.servicerca.controller;import com.servicerca.dto.auth.*;import com.servicerca.service.AuthService;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/auth") public class AuthController{private final AuthService service;public AuthController(AuthService s){service=s;}@PostMapping("/login")public ResponseEntity<AuthResponse>login(@Valid@RequestBody LoginRequest r){return ResponseEntity.ok(service.login(r));}@PostMapping("/register")public ResponseEntity<AuthResponse>register(@Valid@RequestBody RegisterRequest r){return ResponseEntity.status(201).body(service.register(r));}@PostMapping("/refresh")public ResponseEntity<AuthResponse>refresh(@Valid@RequestBody RefreshTokenRequest r){return ResponseEntity.ok(service.refresh(r));}@PostMapping("/forgot-password")public ResponseEntity<Void>forgot(@Valid@RequestBody RecoveryRequest r){service.forgot(r);return ResponseEntity.noContent().build();}@PostMapping("/reset-password")public ResponseEntity<Void>reset(@Valid@RequestBody ResetPasswordRequest r){service.reset(r);return ResponseEntity.noContent().build();}}
